1	package com.example.starter.hazmat.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.LocalDateTime;
7	import java.util.ArrayList;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Optional;
12	
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.PlatformTransactionManager;
16	import org.springframework.transaction.support.TransactionTemplate;
17	
18	import com.example.starter.hazmat.api.ApiException;
19	import com.example.starter.hazmat.clock.MutableClock;
20	import com.example.starter.hazmat.domain.EscortRole;
21	import com.example.starter.hazmat.domain.RelaySegmentStatus;
22	import com.example.starter.hazmat.domain.RouteApprovalStatus;
23	import com.example.starter.hazmat.domain.ShipmentStatus;
24	import com.example.starter.hazmat.domain.WaypointState;
25	import com.example.starter.hazmat.dto.ApplyRequest;
26	import com.example.starter.hazmat.dto.CheckinRequest;
27	import com.example.starter.hazmat.dto.RelayCheckinRequest;
28	import com.example.starter.hazmat.dto.RelayPointRequest;
29	import com.example.starter.hazmat.dto.RerouteRequest;
30	import com.example.starter.hazmat.po.ApprovalWaypoint;
31	import com.example.starter.hazmat.po.Checkin;
32	import com.example.starter.hazmat.po.DisposalRecord;
33	import com.example.starter.hazmat.po.GoodsCategory;
34	import com.example.starter.hazmat.po.IdempotentRecord;
35	import com.example.starter.hazmat.po.NightCurfew;
36	import com.example.starter.hazmat.po.RelayCheckin;
37	import com.example.starter.hazmat.po.RelaySegment;
38	import com.example.starter.hazmat.po.RouteApproval;
39	import com.example.starter.hazmat.po.RouteInfo;
40	import com.example.starter.hazmat.po.RouteWaypointDef;
41	import com.example.starter.hazmat.po.Shipment;
42	import com.example.starter.hazmat.po.ShipmentEvent;
43	import com.example.starter.hazmat.repo.HazmatRepository;
44	import com.fasterxml.jackson.core.JsonProcessingException;
45	import com.fasterxml.jackson.databind.ObjectMapper;
46	
47	/**
48	 * 危化品运输路线管制与押运打卡核心服务。
49	 *
50	 * <p>事务边界：写操作通过 {@link TransactionTemplate} 显式包裹；幂等占位独立于业务事务提交，
51	 * 业务失败（含逆序打卡拒绝）也记录首次结果用于同键重放；逆序告警使用独立事务保证回滚不丢告警。
52	 */
53	@Service
54	public class HazmatService {
55	
56	    /** 事件类型。 */
57	    public static final String EVT_ROUTE_REJECTED = "ROUTE_REJECTED";
58	    public static final String EVT_REROUTE_REJECTED = "REROUTE_REJECTED";
59	    public static final String EVT_REROUTE_SWITCH = "REROUTE_SWITCH";
60	    public static final String EVT_CHECKIN_REVERSED = "CHECKIN_REVERSED";
61	    public static final String EVT_DEVIATION_WARNING = "DEVIATION_WARNING";
62	    public static final String EVT_LOST_CONTACT = "LOST_CONTACT";
63	    public static final String EVT_LATE_CHECKIN_AFTER_CLOSE = "LATE_CHECKIN_AFTER_CLOSE";
64	    public static final String EVT_RELAY_POINT_SET = "RELAY_POINT_SET";
65	    public static final String EVT_RELAY_HANDOVER = "RELAY_HANDOVER";
66	    public static final String EVT_RELAY_CHECKIN_REVERSED = "RELAY_CHECKIN_REVERSED";
67	    public static final String EVT_CURFEW_FROZEN = "CURFEW_FROZEN";
68	
69	    /** 连续超时途经点数达到该值即升级失联（恰 2 个触发）。 */
70	    static final int LOST_CONTACT_CONSECUTIVE_TIMEOUTS = 2;
71	
72	    private final HazmatRepository repository;
73	    private final EventRecorder eventRecorder;
74	    private final MutableClock clock;
75	    private final TransactionTemplate tx;
76	    private final ObjectMapper objectMapper;
77	
78	    public HazmatService(HazmatRepository repository, EventRecorder eventRecorder,
79	                         MutableClock clock, PlatformTransactionManager transactionManager,
80	                         ObjectMapper objectMapper) {
81	        this.repository = repository;
82	        this.eventRecorder = eventRecorder;
83	        this.clock = clock;
84	        this.tx = new TransactionTemplate(transactionManager);
85	        this.objectMapper = objectMapper;
86	    }
87	
88	    private LocalDateTime now() {
89	        return clock.now();
90	    }
91	
92	    // ============================ 运输申请 ============================
93	
94	    public ServiceResult apply(ApplyRequest request) {
95	        String fingerprint = fingerprint("APPLY",
96	                request.requestId(), request.vehiclePlate(), request.goodsCategory(),
97	                request.routeCode(), request.plannedDeparture().toString());
98	        return withIdempotency(request.requestId(), fingerprint,
99	                () -> tx.execute(status -> doApply(request)));
100	    }
101	
102	    private ServiceResult doApply(ApplyRequest request) {
103	        LocalDateTime now = now();
104	        GoodsCategory category = repository.findCategory(request.goodsCategory())
105	                .orElseThrow(() -> ApiException.badRequest("CATEGORY_NOT_FOUND",
106	                        "危化品类别不存在: " + request.goodsCategory()));
107	        RouteInfo route = repository.findRoute(request.routeCode())
108	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
109	                        "路线不存在: " + request.routeCode()));
110	        var vehicle = repository.findVehicle(request.vehiclePlate())
111	                .orElseThrow(() -> ApiException.badRequest("VEHICLE_NOT_FOUND",
112	                        "车辆不存在: " + request.vehiclePlate()));
113	        if (vehicle.frozen()) {
114	            throw ApiException.conflict("VEHICLE_FROZEN",
115	                    "车辆 " + request.vehiclePlate() + " 已因失联冻结，禁止新申请");
116	        }
117	        if (repository.findActiveShipment(request.vehiclePlate()).isPresent()) {
118	            throw ApiException.conflict("VEHICLE_BUSY",
119	                    "车辆 " + request.vehiclePlate() + " 同时刻只允许一个执行中运单");
120	        }
121	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
122	        if (defs.isEmpty()) {
123	            throw ApiException.badRequest("ROUTE_WAYPOINTS_MISSING",
124	                    "路线 " + request.routeCode() + " 未定义途经点");
125	        }
126	
127	        String shipmentNo = "HZ" + request.plannedDeparture().toLocalDate().toString().replace("-", "")
128	                + "-" + Integer.toHexString(request.requestId().hashCode() & 0x7fffffff).toUpperCase();
129	        long shipmentId = repository.insertShipment(shipmentNo, request.vehiclePlate(),
130	                request.goodsCategory(), ShipmentStatus.APPLIED, null,
131	                request.plannedDeparture(), now);
132	        try {
133	            // 主键冲突即并发占用失败：回滚运单，返回 409。
134	            repository.occupyVehicle(request.vehiclePlate(), shipmentId);
135	        } catch (DuplicateKeyException e) {
136	            throw ApiException.conflict("VEHICLE_BUSY",
137	                    "车辆 " + request.vehiclePlate() + " 同时刻只允许一个执行中运单");
138	        }
139	        long approvalId = repository.insertApproval(shipmentId, request.routeCode(), 1,
140	                RouteApprovalStatus.PENDING, null, now);
141	        for (RouteWaypointDef def : defs) {
142	            repository.insertWaypoint(approvalId, shipmentId, def.seq(), def.name(),
143	                    request.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
144	        }
145	        repository.updateCurrentApproval(shipmentId, approvalId);
146	
147	        Map<String, Object> body = baseShipmentView(repository.findShipmentById(shipmentId).orElseThrow());
148	        body.put("message", "申请已受理，等待路线核准");
149	        return ServiceResult.ok(body);
150	    }
151	
152	    // ============================ 路线核准 ============================
153	
154	    public ServiceResult decideApproval(String shipmentNo, boolean approved) {
155	        return tx.execute(status -> doDecide(shipmentNo, approved));
156	    }
157	
158	    private ServiceResult doDecide(String shipmentNo, boolean approved) {
159	        Shipment shipment = loadShipment(shipmentNo);
160	        if (shipment.status() != ShipmentStatus.APPLIED) {
161	            throw ApiException.conflict("INVALID_STATUS",
162	                    "运单当前状态 " + shipment.status() + "，不可路线核准");
163	        }
164	        RouteApproval approval = currentApproval(shipment);
165	        if (approval.status() != RouteApprovalStatus.PENDING || approval.versionNo() != 1) {
166	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "首版路线核准记录状态异常");
167	        }
168	        LocalDateTime now = now();
169	
170	        RouteRuleEvaluator.Result result = evaluate(approval.routeCode(),
171	                shipment.goodsCategory(), shipment.plannedDeparture());
172	        if (!approved || !result.allowed()) {
173	            // 驳回事务必须落库（终态 + 释放车辆占用），故提交后返回 422，而非抛异常回滚。
174	            String reason = approved ? result.message() : "人工驳回";
175	            repository.updateApprovalStatus(approval.id(), RouteApprovalStatus.REJECTED, now);
176	            repository.insertEvent(shipment.id(), EVT_ROUTE_REJECTED, reason, now);
177	            repository.updateStatus(shipment.id(), ShipmentStatus.ROUTE_REJECTED);
178	            repository.releaseVehicle(shipment.vehiclePlate());
179	            Map<String, Object> body = shipmentView(shipmentNo);
180	            body.put("errorCode", "ROUTE_REJECTED");
181	            body.put("message", reason);
182	            return ServiceResult.status(422, body);
183	        }
184	        repository.updateApprovalStatus(approval.id(), RouteApprovalStatus.APPROVED, now);
185	        repository.updateStatus(shipment.id(), ShipmentStatus.ROUTE_APPROVED);
186	        return ServiceResult.ok(shipmentView(shipmentNo));
187	    }
188	
189	    // ============================ 发运 ============================
190	
191	    public ServiceResult dispatch(String shipmentNo, String requestId) {
192	        String fingerprint = fingerprint("DISPATCH", requestId, shipmentNo);
193	        return withIdempotency(requestId, fingerprint,
194	                () -> tx.execute(status -> doDispatch(shipmentNo)));
195	    }
196	
197	    private ServiceResult doDispatch(String shipmentNo) {
198	        Shipment shipment = loadShipment(shipmentNo);
199	        if (shipment.status() == ShipmentStatus.DISPATCHED || shipment.status() == ShipmentStatus.IN_TRANSIT) {
200	            throw ApiException.conflict("ALREADY_DISPATCHED", "运单已发运");
201	        }
202	        if (shipment.status() != ShipmentStatus.ROUTE_APPROVED) {
203	            throw ApiException.conflict("INVALID_STATUS",
204	                    "运单当前状态 " + shipment.status() + "，不可发运");
205	        }
206	        repository.updateStatus(shipment.id(), ShipmentStatus.DISPATCHED);
207	        return ServiceResult.ok(shipmentView(shipmentNo));
208	    }
209	
210	    // ============================ 押运打卡 ============================
211	
212	    public ServiceResult checkin(String shipmentNo, CheckinRequest request) {
213	        String fingerprint = fingerprint("CHECKIN", request.requestId(), shipmentNo,
214	                String.valueOf(request.waypointSeq()), request.checkTime().toString());
215	        // 逆序拒绝走异常路径：告警独立事务落库，业务事务回滚，首次失败响应同样幂等保存。
216	        return withIdempotency(request.requestId(), fingerprint,
217	                () -> tx.execute(status -> doCheckin(shipmentNo, request)));
218	    }
219	
220	    private ServiceResult doCheckin(String shipmentNo, CheckinRequest request) {
221	        Shipment shipment = loadShipment(shipmentNo);
222	        // 行锁串行化打卡与禁行冻结/失联升级的并发终态竞争。
223	        repository.lockShipment(shipment.id());
224	        shipment = repository.findShipmentById(shipment.id()).orElseThrow();
225	        LocalDateTime now = now();
226	
227	        if (shipment.status() == ShipmentStatus.COMPLETED) {
228	            // 结案为终态：迟到打卡不改任何业务状态，只记录迟到事件。
229	            eventRecorder.recordNewTransaction(shipment.id(), EVT_LATE_CHECKIN_AFTER_CLOSE,
230	                    "结案后收到途经点 " + request.waypointSeq() + " 打卡，时刻 " + request.checkTime(), now);
231	            Map<String, Object> body = shipmentView(shipmentNo);
232	            body.put("lateAfterClosed", true);
233	            return ServiceResult.ok(body);
234	        }
235	        if (shipment.status().isTerminal()) {
236	            throw ApiException.conflict("SHIPMENT_TERMINAL",
237	                    "运单终态 " + shipment.status() + "，不可打卡");
238	        }
239	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
240	            throw ApiException.conflict("NOT_DISPATCHED",
241	                    "运单当前状态 " + shipment.status() + "，不可打卡");
242	        }
243	
244	        // 夜间禁行：未在禁行起点前完成换班的运单，恰满起点即在同一事务内冻结并转处置。
245	        if (freezeIfCurfewOverdue(shipment, now)) {
246	            return curfewFrozenResult(shipmentNo);
247	        }
248	        // 换班完成不豁免禁行：打卡时刻落入夜间禁行窗口即拒绝（仅合法时段或获准改线后可通行）。
249	        RouteApproval checkinApproval = currentApproval(shipment);
250	        for (NightCurfew curfew : repository.findNightCurfews(checkinApproval.routeCode())) {
251	            if (!request.checkTime().isBefore(curfew.curfewStart())
252	                    && request.checkTime().isBefore(curfew.curfewEnd())) {
253	                throw ApiException.conflict("NIGHT_CURFEW_PERIOD",
254	                        "打卡时刻 " + request.checkTime() + " 落入夜间禁行时段 [" + curfew.curfewStart()
255	                                + ", " + curfew.curfewEnd() + ")，禁行时段内禁止通行打卡");
256	            }
257	        }
258	
259	        long approvalId = shipment.currentApprovalId();
260	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approvalId);
261	        ApprovalWaypoint target = waypoints.stream()
262	                .filter(w -> w.seq() == request.waypointSeq()).findFirst()
263	                .orElseThrow(() -> ApiException.badRequest("WAYPOINT_NOT_FOUND",
264	                        "当前路线无途经点序号 " + request.waypointSeq()));
265	
266	        Optional<Checkin> duplicate = repository.findCheckin(shipment.id(), approvalId, target.seq());
267	        if (duplicate.isPresent()) {
268	            throw ApiException.conflict("WAYPOINT_ALREADY_CHECKED",
269	                    "途经点 " + target.seq() + " 已打卡（运单+途经点序号去重），首次打卡时刻 "
270	                            + duplicate.get().checkTime());
271	        }
272	
273	        // 时序校验：与最近的前序、后序已打卡途经点比较；乱序回传允许（按时刻归位），时刻逆序拒绝并告警。
274	        Checkin prev = nearestChecked(waypoints, target.seq(), true);
275	        Checkin next = nearestChecked(waypoints, target.seq(), false);
276	        if (prev != null && !request.checkTime().isAfter(prev.checkTime())) {
277	            rejectReverse(shipment, target.seq(), request.checkTime(),
278	                    "晚于前序途经点 " + prev.seq() + " 的打卡时刻 " + prev.checkTime(), now);
279	        }
280	        if (next != null && !request.checkTime().isBefore(next.checkTime())) {
281	            rejectReverse(shipment, target.seq(), request.checkTime(),
282	                    "早于后序途经点 " + next.seq() + " 的打卡时刻 " + next.checkTime(), now);
283	        }
284	
285	        boolean late = !request.checkTime().isBefore(target.deadline());
286	        WaypointState targetState = late ? WaypointState.CHECKED_LATE : WaypointState.CHECKED;
287	        int rows;
288	        if (late) {
289	            // 既可能从未扫描（PENDING），也可能已被标记偏离（TIMED_OUT）。
290	            rows = repository.compareAndSetWaypointState(approvalId, target.seq(),
291	                    WaypointState.PENDING, targetState, request.checkTime())
292	                    + repository.compareAndSetWaypointState(approvalId, target.seq(),
293	                    WaypointState.TIMED_OUT, targetState, request.checkTime());
294	        } else {
295	            rows = repository.compareAndSetWaypointState(approvalId, target.seq(),
296	                    WaypointState.PENDING, targetState, request.checkTime());
297	        }
298	        if (rows == 0) {
299	            // 并发：监控扫描或另一打卡刚刚改变状态。
300	            Optional<Checkin> raced = repository.findCheckin(shipment.id(), approvalId, target.seq());
301	            if (raced.isPresent()) {
302	                throw ApiException.conflict("WAYPOINT_ALREADY_CHECKED",
303	                        "途经点 " + target.seq() + " 已打卡，首次打卡时刻 " + raced.get().checkTime());
304	            }
305	            throw ApiException.conflict("WAYPOINT_STATE_CHANGED",
306	                    "途经点 " + target.seq() + " 状态刚被更新，请重试");
307	        }
308	        repository.insertCheckin(shipment.id(), approvalId, target.seq(),
309	                request.checkTime(), request.requestId(), now);
310	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
311	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
312	        }
313	        return ServiceResult.ok(shipmentView(shipmentNo));
314	    }
315	
316	    private void rejectReverse(Shipment shipment, int seq, LocalDateTime checkTime, String detail, LocalDateTime now) {
317	        String message = "途经点 " + seq + " 打卡时刻 " + checkTime + " 未" + detail + "，逆序拒绝";
318	        eventRecorder.recordNewTransaction(shipment.id(), EVT_CHECKIN_REVERSED, message, now);
319	        throw ApiException.badRequest("CHECKIN_REVERSED", message);
320	    }
321	
322	    /** 查找序号最近的已打卡途经点：backward=true 向前，false 向后（仅限当前生效路线版本）。 */
323	    private Checkin nearestChecked(List<ApprovalWaypoint> waypoints, int seq, boolean backward) {
324	        ApprovalWaypoint result = null;
325	        for (ApprovalWaypoint w : waypoints) {
326	            if (backward ? (w.seq() < seq) : (w.seq() > seq)) {
327	                if (result == null
328	                        || (backward && w.seq() > result.seq())
329	                        || (!backward && w.seq() < result.seq())) {
330	                    result = w;
331	                }
332	            }
333	        }
334	        if (result == null) {
335	            return null;
336	        }
337	        return repository.findCheckin(result.shipmentId(), result.approvalId(), result.seq()).orElse(null);
338	    }
339	
340	    // ============================ 夜间接力押运 ============================
341	
342	    /**
343	     * 设置安全接力点（创建进行中接力段）。
344	     * 约束：途经点计划通过时刻须严格早于夜间禁行起点；运单+途经点序号去重；
345	     * 同一运单同时刻只允许一个进行中接力段（占用表主键冲突即 409）。
346	     */
347	    public ServiceResult setRelayPoint(String shipmentNo, RelayPointRequest request) {
348	        String fingerprint = fingerprint("RELAY_POINT", request.requestId(), shipmentNo,
349	                String.valueOf(request.waypointSeq()));
350	        return withIdempotency(request.requestId(), fingerprint,
351	                () -> tx.execute(status -> doSetRelayPoint(shipmentNo, request)));
352	    }
353	
354	    private ServiceResult doSetRelayPoint(String shipmentNo, RelayPointRequest request) {
355	        Shipment shipment = loadShipment(shipmentNo);
356	        repository.lockShipment(shipment.id());
357	        shipment = repository.findShipmentById(shipment.id()).orElseThrow();
358	        if (shipment.status().isTerminal()) {
359	            throw ApiException.conflict("SHIPMENT_TERMINAL",
360	                    "运单终态 " + shipment.status() + "，不可设置接力点");
361	        }
362	        if (shipment.status() == ShipmentStatus.APPLIED) {
363	            throw ApiException.conflict("INVALID_STATUS", "运单尚未核准路线，不可设置接力点");
364	        }
365	        RouteApproval approval = currentApproval(shipment);
366	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approval.id());
367	        ApprovalWaypoint target = waypoints.stream()
368	                .filter(w -> w.seq() == request.waypointSeq()).findFirst()
369	                .orElseThrow(() -> ApiException.badRequest("WAYPOINT_NOT_FOUND",
370	                        "当前路线无途经点序号 " + request.waypointSeq()));
371	        NightCurfew curfew = applicableCurfew(shipment, waypoints);
372	        if (curfew != null && !target.plannedTime().isBefore(curfew.curfewStart())) {
373	            throw ApiException.badRequest("RELAY_POINT_UNSAFE",
374	                    "途经点 " + target.seq() + " 计划通过时刻 " + target.plannedTime()
375	                            + " 不早于夜间禁行起点 " + curfew.curfewStart() + "，不能作为安全接力点");
376	        }
377	        if (repository.findSegment(shipment.id(), approval.id(), target.seq()).isPresent()) {
378	            throw ApiException.conflict("RELAY_POINT_DUPLICATE",
379	                    "途经点 " + target.seq() + " 已设置接力段（运单+途经点序号去重）");
380	        }
381	        LocalDateTime now = now();
382	        long segmentId;
383	        try {
384	            segmentId = repository.insertRelaySegment(shipment.id(), approval.id(), target.seq(), now);
385	        } catch (DuplicateKeyException e) {
386	            throw ApiException.conflict("RELAY_POINT_DUPLICATE",
387	                    "途经点 " + target.seq() + " 已设置接力段（运单+途经点序号去重）");
388	        }
389	        try {
390	            // 主键冲突即并发占用失败：同一运单同时刻只允许一个进行中接力段。
391	            repository.occupyRelay(shipment.id(), segmentId);
392	        } catch (DuplicateKeyException e) {
393	            throw ApiException.conflict("RELAY_SEGMENT_ACTIVE",
394	                    "同一运单同时刻只允许一个进行中接力段");
395	        }
396	        repository.insertEvent(shipment.id(), EVT_RELAY_POINT_SET,
397	                "设置安全接力点：途经点 " + target.seq() + "(" + target.name() + ")，计划通过 "
398	                        + target.plannedTime(), now);
399	        Map<String, Object> body = shipmentView(shipmentNo);
400	        body.put("relaySegmentId", segmentId);
401	        return ServiceResult.ok(body);
402	    }
