404	    /**
405	     * 接力双人打卡：交班（OUT）与接班（IN）各一条，双方编号须不同（单人打卡不生效）；
406	     * 接班时刻须严格晚于交班时刻，否则逆序拒绝并告警；双方齐全即完成换班并释放接力段占用。
407	     */
408	    public ServiceResult relayCheckin(String shipmentNo, RelayCheckinRequest request) {
409	        String fingerprint = fingerprint("RELAY_CHECKIN", request.requestId(), shipmentNo,
410	                request.escortId(), request.role(), request.checkTime().toString());
411	        return withIdempotency(request.requestId(), fingerprint,
412	                () -> tx.execute(status -> doRelayCheckin(shipmentNo, request)));
413	    }
414	
415	    private ServiceResult doRelayCheckin(String shipmentNo, RelayCheckinRequest request) {
416	        EscortRole role = EscortRole.parse(request.role());
417	        if (role == null) {
418	            throw ApiException.badRequest("INVALID_ROLE",
419	                    "打卡角色须为 OUT（交班）或 IN（接班）: " + request.role());
420	        }
421	        Shipment shipment = loadShipment(shipmentNo);
422	        // 行锁串行化换班完成与禁行冻结的并发终态竞争。
423	        repository.lockShipment(shipment.id());
424	        shipment = repository.findShipmentById(shipment.id()).orElseThrow();
425	        LocalDateTime now = now();
426	        if (shipment.status().isTerminal()) {
427	            throw ApiException.conflict("SHIPMENT_TERMINAL",
428	                    "运单终态 " + shipment.status() + "，不可接力打卡");
429	        }
430	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
431	            throw ApiException.conflict("NOT_DISPATCHED",
432	                    "运单当前状态 " + shipment.status() + "，不可接力打卡");
433	        }
434	        // 恰满禁行起点即判超时：懒冻结（冻结与处置登记同一事务提交）后返回 409。
435	        if (freezeIfCurfewOverdue(shipment, now)) {
436	            return curfewFrozenResult(shipmentNo);
437	        }
438	        RelaySegment segment = repository.findActiveSegment(shipment.id())
439	                .orElseThrow(() -> ApiException.conflict("RELAY_SEGMENT_NOT_FOUND",
440	                        "运单无进行中接力段，请先设置安全接力点"));
441	        RouteApproval approval = currentApproval(shipment);
442	        NightCurfew curfew = applicableCurfew(shipment, repository.findWaypoints(approval.id()));
443	        if (curfew != null && !request.checkTime().isBefore(curfew.curfewStart())) {
444	            throw ApiException.badRequest("RELAY_CHECKIN_TOO_LATE",
445	                    "接力打卡时刻 " + request.checkTime() + " 须严格早于夜间禁行起点 " + curfew.curfewStart());
446	        }
447	        if (repository.findRelayCheckin(segment.id(), role).isPresent()) {
448	            throw ApiException.conflict("RELAY_CHECKIN_DUPLICATE",
449	                    "接力点 " + segment.relaySeq() + " 角色 " + role + " 已打卡（运单+途经点序号去重）");
450	        }
451	        Optional<RelayCheckin> outCk = repository.findRelayCheckin(segment.id(), EscortRole.OUT);
452	        Optional<RelayCheckin> inCk = repository.findRelayCheckin(segment.id(), EscortRole.IN);
453	        Optional<RelayCheckin> opposite = role == EscortRole.OUT ? inCk : outCk;
454	        if (opposite.isPresent() && opposite.get().escortId().equals(request.escortId())) {
455	            throw ApiException.badRequest("RELAY_SAME_ESCORT",
456	                    "交接班押运员编号相同（" + request.escortId() + "），单人打卡不生效");
457	        }
458	        // 时序校验：接班时刻须严格晚于交班时刻；乱序回传按时刻归位，逆序拒绝并告警。
459	        if (role == EscortRole.IN && outCk.isPresent()
460	                && !request.checkTime().isAfter(outCk.get().checkTime())) {
461	            rejectRelayReverse(shipment, segment, request,
462	                    "未晚于交班时刻 " + outCk.get().checkTime(), now);
463	        }
464	        if (role == EscortRole.OUT && inCk.isPresent()
465	                && !inCk.get().checkTime().isAfter(request.checkTime())) {
466	            rejectRelayReverse(shipment, segment, request,
467	                    "交班后已有接班时刻 " + inCk.get().checkTime() + " 不晚于本次交班时刻", now);
468	        }
469	        repository.insertRelayCheckin(segment.id(), shipment.id(), request.escortId(), role,
470	                request.checkTime(), request.requestId(), now);
471	
472	        Optional<RelayCheckin> outFinal = repository.findRelayCheckin(segment.id(), EscortRole.OUT);
473	        Optional<RelayCheckin> inFinal = repository.findRelayCheckin(segment.id(), EscortRole.IN);
474	        Map<String, Object> body;
475	        if (outFinal.isPresent() && inFinal.isPresent()) {
476	            RelayCheckin out = outFinal.get();
477	            RelayCheckin in = inFinal.get();
478	            int rows = repository.completeSegment(segment.id(), out.escortId(), out.checkTime(),
479	                    in.escortId(), in.checkTime(), in.checkTime());
480	            if (rows == 0) {
481	                throw ApiException.conflict("RELAY_SEGMENT_CLOSED", "接力段已被并发完成或冻结，请重试");
482	            }
483	            repository.releaseRelay(shipment.id());
484	            repository.insertEvent(shipment.id(), EVT_RELAY_HANDOVER,
485	                    "接力点 " + segment.relaySeq() + " 换班完成：交班 " + out.escortId() + "@"
486	                            + out.checkTime() + "，接班 " + in.escortId() + "@" + in.checkTime(), now);
487	            body = shipmentView(shipmentNo);
488	            body.put("handoverCompleted", true);
489	        } else {
490	            // 单人打卡不生效：仅记录一侧打卡，换班未完成。
491	            body = shipmentView(shipmentNo);
492	            body.put("handoverCompleted", false);
493	            body.put("message", "已记录 " + role + " 打卡，待对方打卡后换班生效（单人打卡不生效）");
494	        }
495	        return ServiceResult.ok(body);
496	    }
