498	    private void rejectRelayReverse(Shipment shipment, RelaySegment segment,
499	                                    RelayCheckinRequest request, String detail, LocalDateTime now) {
500	        String message = "接力点 " + segment.relaySeq() + " " + request.role() + " 打卡时刻 "
501	                + request.checkTime() + " " + detail + "，逆序拒绝";
502	        eventRecorder.recordNewTransaction(shipment.id(), EVT_RELAY_CHECKIN_REVERSED, message, now);
503	        throw ApiException.badRequest("RELAY_CHECKIN_REVERSED", message);
