579	    // ============================ 紧急改线 ============================
580	
581	    public ServiceResult reroute(String shipmentNo, RerouteRequest request) {
582	        String fingerprint = fingerprint("REROUTE", request.requestId(), shipmentNo, request.routeCode());
583	        return withIdempotency(request.requestId(), fingerprint,
584	                () -> tx.execute(status -> doReroute(shipmentNo, request)));
585	    }
586	
587	    private ServiceResult doReroute(String shipmentNo, RerouteRequest request) {
588	        Shipment shipment = loadShipment(shipmentNo);
589	        if (shipment.status().isTerminal()) {
590	            throw ApiException.conflict("SHIPMENT_TERMINAL", "运单已终态，不可改线");
591	        }
592	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
593	            throw ApiException.conflict("INVALID_STATUS", "仅发运后可紧急改线，当前 " + shipment.status());
594	        }
595	        repository.findRoute(request.routeCode())
596	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
597	                        "路线不存在: " + request.routeCode()));
598	        List<RouteApproval> approvals = repository.findApprovals(shipment.id());
599	        boolean pendingExists = approvals.stream()
600	                .anyMatch(a -> a.status() == RouteApprovalStatus.PENDING);
601	        if (pendingExists) {
602	            throw ApiException.conflict("REROUTE_PENDING", "已有待核准改线申请，请先完成核准");
603	        }
604	        int nextVersion = approvals.stream().mapToInt(RouteApproval::versionNo).max().orElse(0) + 1;
605	        LocalDateTime now = now();
606	        long newApprovalId = repository.insertApproval(shipment.id(), request.routeCode(), nextVersion,
607	                RouteApprovalStatus.PENDING, null, now);
608	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
609	        for (RouteWaypointDef def : defs) {
610	            repository.insertWaypoint(newApprovalId, shipment.id(), def.seq(), def.name(),
611	                    shipment.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
612	        }
613	        Map<String, Object> body = shipmentView(shipmentNo);
614	        body.put("pendingApprovalId", newApprovalId);
615	        body.put("message", "改线申请已提交，核准通过前原路线打卡继续有效");
616	        return ServiceResult.ok(body);
617	    }
618	
619	    public ServiceResult approveReroute(String shipmentNo, long approvalId) {
620	        return tx.execute(status -> doApproveReroute(shipmentNo, approvalId));
621	    }
622	
623	    private ServiceResult doApproveReroute(String shipmentNo, long approvalId) {
624	        Shipment shipment = loadShipment(shipmentNo);
625	        RouteApproval next = repository.findApproval(approvalId)
626	                .orElseThrow(() -> ApiException.notFound("APPROVAL_NOT_FOUND", "核准记录不存在"));
627	        if (next.shipmentId() != shipment.id()) {
628	            throw ApiException.badRequest("APPROVAL_MISMATCH", "核准记录不属于该运单");
629	        }
630	        if (next.status() != RouteApprovalStatus.PENDING || next.versionNo() <= 1) {
631	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "该记录不是待核准改线申请");
632	        }
633	        LocalDateTime now = now();
634	        RouteRuleEvaluator.Result result = evaluate(next.routeCode(),
635	                shipment.goodsCategory(), shipment.plannedDeparture());
636	        if (!result.allowed()) {
637	            // 改线驳回仅落库新记录的驳回结果，原路线继续有效；提交后返回 422。
638	            repository.updateApprovalStatus(next.id(), RouteApprovalStatus.REJECTED, now);
639	            repository.insertEvent(shipment.id(), EVT_REROUTE_REJECTED, result.message(), now);
640	            Map<String, Object> body = shipmentView(shipmentNo);
641	            body.put("errorCode", "REROUTE_REJECTED");
642	            body.put("message", result.message());
643	            return ServiceResult.status(422, body);
644	        }
645	        // 同一事务：旧路线终止 + 新路线生效 + 运单指向切换。
646	        RouteApproval old = currentApproval(shipment);
647	        repository.updateApprovalStatus(old.id(), RouteApprovalStatus.TERMINATED, now);
648	        repository.updateApprovalStatus(next.id(), RouteApprovalStatus.APPROVED, now);
649	        repository.updateCurrentApproval(shipment.id(), next.id());
650	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
651	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
652	        }
653	        repository.insertEvent(shipment.id(), EVT_REROUTE_SWITCH,
654	                "路线由 " + old.routeCode() + "(v" + old.versionNo() + ") 切换为 "
655	                        + next.routeCode() + "(v" + next.versionNo() + ")，原路线打卡保留", now);
656	        return ServiceResult.ok(shipmentView(shipmentNo));
657	    }
