659	    // ============================ 到达核销 ============================
660	
661	    public ServiceResult complete(String shipmentNo, String requestId) {
662	        String fingerprint = fingerprint("COMPLETE", requestId, shipmentNo);
663	        return withIdempotency(requestId, fingerprint,
664	                () -> tx.execute(status -> doComplete(shipmentNo)));
665	    }
666	
667	    private ServiceResult doComplete(String shipmentNo) {
668	        Shipment shipment = loadShipment(shipmentNo);
669	        if (shipment.status() == ShipmentStatus.COMPLETED) {
670	            // 结案终态：重复核销（无论是否同 requestId）返回幂等成功。
671	            return ServiceResult.ok(shipmentView(shipmentNo));
672	        }
673	        if (shipment.status() == ShipmentStatus.LOST_CONTACT) {
674	            throw ApiException.conflict("ALREADY_LOST_CONTACT", "运单已失联冻结，不可核销");
675	        }
676	        if (shipment.status() == ShipmentStatus.CURFEW_FROZEN) {
677	            throw ApiException.conflict("ALREADY_CURFEW_FROZEN", "运单已禁行冻结转处置，不可核销");
678	        }
679	        // 条件更新：与失联升级/禁行冻结竞争，败者拿不到终态。
680	        int rows = repository.compareAndSetTerminal(shipment.id(), ShipmentStatus.COMPLETED);
681	        if (rows == 0) {
682	            Shipment current = repository.findShipmentById(shipment.id()).orElseThrow();
683	            if (current.status() == ShipmentStatus.COMPLETED) {
684	                return ServiceResult.ok(shipmentView(shipmentNo));
685	            }
686	            if (current.status() == ShipmentStatus.CURFEW_FROZEN) {
687	                throw ApiException.conflict("ALREADY_CURFEW_FROZEN", "运单已禁行冻结转处置，不可核销");
688	            }
689	            throw ApiException.conflict("ALREADY_LOST_CONTACT", "运单已失联冻结，不可核销");
690	        }
691	        repository.releaseVehicle(shipment.vehiclePlate());
692	        return ServiceResult.ok(shipmentView(shipmentNo));
693	    }
