695	    // ============================ 超时/失联监控（可复算） ============================
696	
697	    public ServiceResult scanTimeouts(LocalDateTime at) {
698	        LocalDateTime now = at != null ? at : now();
699	        List<Map<String, Object>> affected = new ArrayList<>();
700	        List<Shipment> actives;
701	        try {
702	            actives = tx.execute(status -> repository.findActiveShipments());
703	        } catch (Exception e) {
704	            throw ApiException.badRequest("SCAN_FAILED", e.getMessage());
705	        }
706	        for (Shipment shipment : actives) {
707	            if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
708	                continue;
709	            }
710	            try {
711	                Map<String, Object> changed = tx.execute(status -> scanOne(shipment.id(), now));
712	                if (changed != null && Boolean.TRUE.equals(changed.get("changed"))) {
713	                    affected.add(changed);
714	                }
715	            } catch (ApiException e) {
716	                throw e;
717	            } catch (Exception ignored) {
718	                // 单个运单扫描失败不影响其他运单（终态竞争败者等）。
719	            }
720	        }
721	        return ServiceResult.ok(Map.of("scanAt", now.toString(), "affected", affected));
722	    }
723	
724	    /** 扫描单个运单：标记超时点；夜间禁行冻结与连续 2 点超时失联共用终态 CAS，保证唯一终态。 */
725	    private Map<String, Object> scanOne(long shipmentId, LocalDateTime now) {
726	        repository.lockShipment(shipmentId);
727	        Shipment shipment = repository.findShipmentById(shipmentId).orElseThrow();
728	        if (shipment.status().isTerminal()) {
729	            return Map.of();
730	        }
731	        long approvalId = shipment.currentApprovalId();
732	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approvalId);
733	        List<Integer> timedOut = new ArrayList<>();
734	        for (ApprovalWaypoint w : waypoints) {
735	            if (w.state() == WaypointState.PENDING && !now.isBefore(w.deadline())) {
736	                int rows = repository.compareAndSetWaypointState(approvalId, w.seq(),
737	                        WaypointState.PENDING, WaypointState.TIMED_OUT, null);
738	                if (rows == 1) {
739	                    timedOut.add(w.seq());
740	                    repository.insertEvent(shipmentId, EVT_DEVIATION_WARNING,
741	                            "途经点 " + w.seq() + "(" + w.name() + ") 计划通过时刻 " + w.plannedTime()
742	                                    + "，超时阈值 " + w.deadline() + "，扫描时刻 " + now + " 仍未打卡", now);
743	                }
744	            }
745	        }
746	        // 偏离预警与禁行冻结同时命中：先判禁行冻结，冻结成功即唯一终态，不再继续计程/升级失联。
747	        boolean curfewFrozen = freezeIfCurfewOverdue(shipment, now);
748	        boolean upgraded = false;
749	        if (!curfewFrozen) {
750	            boolean lost = hasConsecutiveTimeouts(repository.findWaypoints(approvalId));
751	            if (lost) {
752	                int rows = repository.compareAndSetTerminal(shipmentId, ShipmentStatus.LOST_CONTACT);
753	                if (rows == 1) {
754	                    upgraded = true;
755	                    repository.freezeVehicle(shipment.vehiclePlate(), shipmentId, now);
756	                    repository.releaseVehicle(shipment.vehiclePlate());
757	                    repository.insertEvent(shipmentId, EVT_LOST_CONTACT,
758	                            "连续 2 个途经点超时未打卡，升级失联并冻结车辆 " + shipment.vehiclePlate(), now);
759	                }
760	            }
761	        }
762	        if (timedOut.isEmpty() && !upgraded && !curfewFrozen) {
763	            return Map.of();
764	        }
765	        Map<String, Object> changed = new LinkedHashMap<>();
766	        changed.put("changed", true);
767	        changed.put("shipmentNo", shipment.shipmentNo());
768	        changed.put("newlyTimedOut", timedOut);
769	        changed.put("lostContact", upgraded);
770	        changed.put("curfewFrozen", curfewFrozen);
771	        return changed;
772	    }
773	
774	    /** 连续超时判定：按序号相邻的两个途经点均处于 TIMED_OUT（恰 2 个即触发）。 */
775	    static boolean hasConsecutiveTimeouts(List<ApprovalWaypoint> waypoints) {
776	        List<ApprovalWaypoint> sorted = waypoints.stream()
777	                .sorted(java.util.Comparator.comparingInt(ApprovalWaypoint::seq)).toList();
778	        int consecutive = 0;
779	        for (ApprovalWaypoint w : sorted) {
780	            if (w.state() == WaypointState.TIMED_OUT) {
781	                consecutive++;
782	                if (consecutive >= LOST_CONTACT_CONSECUTIVE_TIMEOUTS) {
783	                    return true;
784	                }
785	            } else {
786	                consecutive = 0;
787	            }
788	        }
789	        return false;
790	    }
791	
792	    // ============================ 查询视图 ============================
