809	        GoodsCategory category = repository.findCategory(categoryCode)
810	                .orElseThrow(() -> ApiException.badRequest("CATEGORY_NOT_FOUND", "危化品类别不存在"));
811	        RouteInfo route = repository.findRoute(routeCode)
812	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND", "路线不存在"));
813	        return RouteRuleEvaluator.evaluate(route, category.requiredLevel(), departure,
814	                repository.findWaypointDefs(routeCode), repository.findControlPeriods(routeCode));
815	    }
