828	    private Map<String, Object> shipmentView(String shipmentNo) {
829	        Shipment shipment = loadShipment(shipmentNo);
830	        Map<String, Object> body = baseShipmentView(shipment);
831	        repository.findVehicle(shipment.vehiclePlate()).ifPresent(v -> body.put("vehicleFrozen", v.frozen()));
832	
833	        List<Map<String, Object>> approvalViews = new ArrayList<>();
834	        for (RouteApproval approval : repository.findApprovals(shipment.id())) {
835	            Map<String, Object> av = new LinkedHashMap<>();
836	            av.put("approvalId", approval.id());
