870	        body.put("events", eventViews);
871	
872	        // 夜间接力押运视图：接力段（含双人打卡）、禁行规则、处置登记。
873	        List<Map<String, Object>> segmentViews = new ArrayList<>();
874	        for (RelaySegment segment : repository.findSegments(shipment.id())) {
