882	            sv.put("inTime", segment.inTime() == null ? null : segment.inTime().toString());
883	            sv.put("completedAt", segment.completedAt() == null ? null : segment.completedAt().toString());
884	            List<Map<String, Object>> checkinViews = new ArrayList<>();
885	            for (RelayCheckin c : repository.findRelayCheckins(segment.id())) {
886	                Map<String, Object> cv = new LinkedHashMap<>();
