896	
897	        if (shipment.currentApprovalId() != null) {
898	            RouteApproval current = currentApproval(shipment);
899	            List<Map<String, Object>> curfewViews = new ArrayList<>();
900	            for (NightCurfew curfew : repository.findNightCurfews(current.routeCode())) {
901	                Map<String, Object> cv = new LinkedHashMap<>();
