924	
925	    // ============================ 幂等支撑 ============================
926	
927	    /**
928	     * 以 requestId 幂等执行业务动作：
929	     * <ul>
930	     *   <li>同键同参：返回首次结果（成功或业务失败，含首次 HTTP 状态码）；</li>
931	     *   <li>同键异参：指纹不符返回 409；</li>
932	     *   <li>处理中并发：返回 409。</li>
933	     * </ul>
934	     */
935	    private ServiceResult withIdempotency(String requestId, String fingerprint,
936	                                          java.util.function.Supplier<ServiceResult> action) {
937	        for (int attempt = 0; attempt < 2; attempt++) {
938	            Optional<IdempotentRecord> existing = repository.findIdempotent(requestId);
939	            if (existing.isPresent()) {
940	                IdempotentRecord record = existing.get();
941	                if (!record.fingerprint().equals(fingerprint)) {
942	                    throw ApiException.conflict("IDEMPOTENT_FINGERPRINT_MISMATCH",
943	                            "requestId=" + requestId + " 已用于不同业务参数");
944	                }
945	                if ("COMPLETED".equals(record.status())) {
946	                    Map<String, Object> stored = parseJson(record.responseBody());
947	                    // 非 2xx 首次结果以相同状态码/错误码重放，保持 HTTP 语义一致。
948	                    if (record.httpStatus() != null && record.httpStatus() >= 400) {
949	                        Object code = stored.get("errorCode");
950	                        if (code == null) {
951	                            code = stored.get("code");
952	                        }
953	                        throw new ApiException(org.springframework.http.HttpStatus.valueOf(record.httpStatus()),
954	                                code == null ? "IDEMPOTENT_REPLAY" : code.toString(),
955	                                stored.get("message") == null ? "" : stored.get("message").toString());
956	                    }
957	                    return new ServiceResult(record.httpStatus(), stored);
958	                }
959	                throw ApiException.conflict("IDEMPOTENT_PROCESSING",
960	                        "相同 requestId 请求正在处理中");
961	            }
962	            boolean inserted = repository.insertProcessingIdempotent(requestId, fingerprint, now());
963	            if (!inserted) {
964	                continue; // 并发插入竞争：重读记录走重放分支
965	            }
966	            try {
967	                ServiceResult result = action.get();
968	                repository.completeIdempotent(requestId, result.httpStatus(), toJson(result.body()));
969	                return result;
970	            } catch (ApiException e) {
971	                Map<String, Object> errorBody = Map.of(
972	                        "code", e.getCode(),
973	                        "message", e.getMessage() == null ? "" : e.getMessage());
974	                repository.completeIdempotent(requestId, e.getStatus().value(), toJson(errorBody));
975	                throw e;
976	            } catch (RuntimeException e) {
977	                // 系统异常：保留 PROCESSING 之外，直接抛出（占位不删除，便于排查）。
978	                throw e;
979	            }
980	        }
981	        throw ApiException.conflict("IDEMPOTENT_RACE", "幂等记录并发竞争，请稍后重试");
982	    }
983	
984	    @SuppressWarnings("unchecked")
985	    private Map<String, Object> parseJson(String json) {
986	        if (json == null || json.isBlank()) {
987	            return Map.of();
988	        }
989	        try {
990	            return objectMapper.readValue(json, Map.class);
991	        } catch (JsonProcessingException e) {
992	            return Map.of("raw", json);
993	        }
994	    }
995	
996	    private String toJson(Map<String, Object> body) {
997	        try {
998	            return objectMapper.writeValueAsString(body);
999	        } catch (JsonProcessingException e) {
1000	            throw new IllegalStateException("响应序列化失败", e);
1001	        }
1002	    }
1003	
1004	    private static String fingerprint(String operation, Object... parts) {
1005	        StringBuilder sb = new StringBuilder(operation);
1006	        for (Object part : parts) {
1007	            sb.append('|').append(part);
1008	        }
1009	        try {
1010	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
1011	            byte[] hash = digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
1012	            StringBuilder hex = new StringBuilder();
1013	            for (byte b : hash) {
1014	                hex.append(String.format("%02x", b));
1015	            }
1016	            return hex.toString();
1017	        } catch (NoSuchAlgorithmException e) {
1018	            throw new IllegalStateException(e);
1019	        }
1020	    }
1021	}
