1	package com.example.starter.hazmat.api;
2	
3	import java.time.LocalDateTime;
4	import java.util.Map;
5	
6	import jakarta.validation.Valid;
7	
8	import org.springframework.http.ResponseEntity;
9	import org.springframework.web.bind.annotation.GetMapping;
10	import org.springframework.web.bind.annotation.PathVariable;
11	import org.springframework.web.bind.annotation.PostMapping;
12	import org.springframework.web.bind.annotation.RequestBody;
13	import org.springframework.web.bind.annotation.RequestParam;
14	import org.springframework.web.bind.annotation.RestController;
15	
16	import com.example.starter.hazmat.dto.ApplyRequest;
17	import com.example.starter.hazmat.dto.CheckinRequest;
18	import com.example.starter.hazmat.dto.IdempotentRequest;
19	import com.example.starter.hazmat.dto.RelayCheckinRequest;
20	import com.example.starter.hazmat.dto.RelayPointRequest;
21	import com.example.starter.hazmat.dto.RerouteRequest;
22	import com.example.starter.hazmat.service.HazmatService;
23	import com.example.starter.hazmat.service.ServiceResult;
24	
25	/**
26	 * 危化品运输监管 REST 入口。
27	 *
28	 * <ul>
29	 *   <li>POST /api/shipments/apply 运输申请（requestId 幂等）</li>
30	 *   <li>POST /api/shipments/{no}/approvals/decide?approved=true|false 路线核准</li>
31	 *   <li>POST /api/shipments/{no}/dispatch 发运</li>
32	 *   <li>POST /api/shipments/{no}/checkins 押运打卡（运单+途经点序号去重）</li>
33	 *   <li>POST /api/shipments/{no}/relay-points 设置安全接力点（创建接力段）</li>
34	 *   <li>POST /api/shipments/{no}/relay-checkins 接力双人打卡（交班/接班）</li>
35	 *   <li>POST /api/shipments/{no}/reroute 紧急改线申请</li>
36	 *   <li>POST /api/shipments/{no}/approvals/{id}/approve 改线核准（原子切换）</li>
37	 *   <li>POST /api/shipments/{no}/complete 到达核销（结案终态）</li>
38	 *   <li>GET  /api/shipments/{no} 运单详情（状态/途经点/事件，可复算视图）</li>
39	 *   <li>POST /api/monitor/scan?at=yyyy-MM-ddTHH:mm:ss 超时/失联监控扫描</li>
40	 * </ul>
41	 */
42	@RestController
43	public class HazmatController {
44	
45	    private final HazmatService service;
46	
47	    public HazmatController(HazmatService service) {
48	        this.service = service;
49	    }
50	
51	    @PostMapping("/api/shipments/apply")
52	    public ResponseEntity<Map<String, Object>> apply(@Valid @RequestBody ApplyRequest request) {
53	        return toEntity(service.apply(request));
54	    }
55	
56	    @PostMapping("/api/shipments/{shipmentNo}/approvals/decide")
57	    public ResponseEntity<Map<String, Object>> decide(@PathVariable String shipmentNo,
