1	package com.example.starter.hazmat;
2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import java.time.LocalDateTime;
6	import java.util.Map;
7	import java.util.concurrent.CountDownLatch;
8	import java.util.concurrent.ExecutorService;
9	import java.util.concurrent.Executors;
10	import java.util.concurrent.TimeUnit;
11	import java.util.concurrent.atomic.AtomicReference;
12	
13	import org.junit.jupiter.api.Test;
14	
15	import com.example.starter.hazmat.api.ApiException;
16	import com.example.starter.hazmat.service.ServiceResult;
17	
18	/**
19	 * 换班完成与禁行冻结并发：恰在禁行起点前后，接班打卡与监控扫描竞争，
20	 * 行锁 + 终态 CAS 保证唯一终态——不得既完成换班又被冻结，也不得既冻结又继续计程。
21	 * 两侧胜负由真实调度决定，只断言终态唯一与数据自洽。
22	 */
23	class ConcurrentRelayFreezeTest extends HazmatIntegrationTestBase {
24	
25	    private static final LocalDateTime DEPARTURE = LocalDateTime.parse("2026-10-02T22:30:00");
26	    private static final LocalDateTime CURFEW_START = LocalDateTime.parse("2026-10-03T00:00:00");
27	
28	    @Test
29	    void handoverAndCurfewFreezeRaceYieldsSingleTerminal() throws Exception {
30	        final int rounds = 6;
31	        int handoverWins = 0;
32	        int freezeWins = 0;
33	
34	        for (int round = 0; round < rounds; round++) {
35	            String plate = "接力车-" + round;
36	            jdbc.update("INSERT INTO vehicle (plate, frozen, frozen_shipment_id, frozen_at) VALUES (?, 0, NULL, NULL)",
37	                    plate);
38	            String no = shipmentNo(apply("race-apply-" + round, plate, "FLAMMABLE", "R-G3", DEPARTURE));
39	            approve(no);
40	            dispatch(no, "race-dispatch-" + round);
41	            setRelayPoint(no, "race-rp-" + round, 1);
42	            // 交班已打卡，只剩接班一脚；业务时钟固定在禁行起点前 1 分钟。
43	            clock.setTime(LocalDateTime.parse("2026-10-02T23:59:00"));
44	            relayCheckin(no, "race-out-" + round, "ESC-01", "OUT",
45	                    LocalDateTime.parse("2026-10-02T23:50:00"));
46	
47	            final String shipmentNo = no;
48	            final int roundNo = round;
49	            CountDownLatch start = new CountDownLatch(1);
50	            AtomicReference<String> handoverOutcome = new AtomicReference<>("none");
51	            ExecutorService pool = Executors.newFixedThreadPool(2);
52	            try {
53	                pool.submit(() -> {
54	                    await(start);
55	                    try {
56	                        ServiceResult result = relayCheckin(shipmentNo, "race-in-" + roundNo, "ESC-02", "IN",
57	                                LocalDateTime.parse("2026-10-02T23:58:00"));
58	                        handoverOutcome.set(result.httpStatus() == 200 ? "COMPLETED" : "HTTP" + result.httpStatus());
59	                    } catch (ApiException e) {
60	                        handoverOutcome.set("REJECTED:" + e.getCode());
61	                    }
62	                });
63	                pool.submit(() -> {
64	                    await(start);
65	                    scan(CURFEW_START);
66	                });
67	                start.countDown();
68	            } finally {
69	                pool.shutdown();
70	                assertThat(pool.awaitTermination(20, TimeUnit.SECONDS)).isTrue();
71	            }
72	
73	            Map<String, Object> view = view(no);
74	            String finalStatus = (String) view.get("status");
75	            Map<String, Object> segment = relaySegments(view).stream()
76	                    .filter(s -> Integer.valueOf(1).equals(s.get("relaySeq")))
77	                    .findFirst().orElseThrow();
78	            if ("CURFEW_FROZEN".equals(finalStatus)) {
79	                freezeWins++;
80	                // 冻结终态自洽：处置登记同事务落库，接力段 FROZEN，接班打卡未生效。
81	                assertThat(disposals(view)).hasSize(1);
82	                assertThat(segment.get("status")).isEqualTo("FROZEN");
83	                assertThat(segment.get("inEscortId")).isNull();
84	                assertThat(handoverOutcome.get()).startsWith("REJECTED");
85	            } else {
86	                handoverWins++;
87	                // 换班赢面：接力段 COMPLETED，运单未冻结，无处置登记。
88	                assertThat(segment.get("status")).isEqualTo("COMPLETED");
89	                assertThat(finalStatus).isIn("DISPATCHED", "IN_TRANSIT");
90	                assertThat(disposals(view)).isEmpty();
91	                assertThat(handoverOutcome.get()).isEqualTo("COMPLETED");
92	            }
93	        }
94	        System.out.println("handoverWins=" + handoverWins + ", freezeWins=" + freezeWins);
95	    }
