        ps.setLong(1, shipmentId);
        ps.setLong(2, approvalId);
        ps.setInt(3, relaySeq);
        ps.setTimestamp(4, Timestamp.valueOf(now));
        return ps;
    }, keyHolder);
    return keyHolder.getKey().longValue();
}

