private void enforceReservationGate(Shipment shipment, RelaySegment segment, RelayCheckinRequest request, LocalDateTime now) {
    // 人员行锁：与资格撤销串行化，形成一致次序。
    repository.lockEscort(request.escortId());
    EscortReservation reservation = repository.findActiveReservationBySegment(segment.id())
            .orElseThrow(() -> ApiException.conflict("RELAY_RESERVATION_REQUIRED",
                    "受控接力段须先完成人员资格预约，方可接班确认"));
    if (!reservation.escortId().equals(request.escortId())) {
        throw ApiException.conflict("RELAY_RESERVATION_ESCORT_MISMATCH",
                "受控段接班确认须来自预约人员 " + reservation.escortId() + "，实际 " + request.escortId());
    }
    // 实际接班时刻（Asia/Shanghai）换算 UTC 后须落在班段 [start,end) 内；恰到 end 拒绝。
    LocalDateTime checkTimeUtc = toUtc(request.checkTime());
    if (checkTimeUtc.isBefore(reservation.shiftStart()) || !checkTimeUtc.isBefore(reservation.shiftEnd())) {
        throw ApiException.badRequest("RELAY_SHIFT_OUT_OF_RANGE",
                "实际接班时刻 " + request.checkTime() + "（UTC " + checkTimeUtc + "）未落在预约班段 ["
                        + reservation.shiftStart() + ", " + reservation.shiftEnd() + ") 内");
    }
    // 重查资格未撤销（与撤销并发时由人员行锁保证一致次序）。
    EscortQualification qual = repository.findQualification(reservation.qualificationId())
            .orElseThrow(() -> ApiException.conflict("QUALIFICATION_NOT_FOUND", "预约资格不存在"));
    if (qual.revoked()) {
        throw ApiException.conflict("QUALIFICATION_REVOKED",
                "接班员 " + request.escortId() + " 资格已撤销，禁止接班确认");
    }
}

private static LocalDateTime toUtc(LocalDateTime shanghaiTime) {
    return shanghaiTime.atZone(MutableClock.ZONE).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();
}
